package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.IOException;
import java.util.*;
import org.apache.ratis.client.RaftClient;
import org.apache.ratis.conf.RaftProperties;
import org.apache.ratis.grpc.GrpcConfigKeys;
import org.apache.ratis.proto.RaftProtos.*;
import org.apache.ratis.protocol.*;
import org.apache.ratis.thirdparty.com.google.protobuf.ByteString;
import org.apache.ratis.util.SizeInBytes;

/** Bounded actual Ratis reads, source-image actions and conditional voter/listener administration. */
public final class RatisRelocationDataClient implements AutoCloseable {
    private final UUID cluster,database,catalogue;private final RatisClientPool clients;private int active;private boolean closing;
    public RatisRelocationDataClient(UUID cluster,UUID database,UUID catalogue){this(cluster,database,catalogue,r->connected(r,null),RatisRelocationDataClient::connected);}
    RatisRelocationDataClient(UUID cluster,UUID database,UUID catalogue,RatisClientPool.Factory leaders,RatisClientPool.OwnerFactory owners){this.cluster=Objects.requireNonNull(cluster);this.database=Objects.requireNonNull(database);this.catalogue=Objects.requireNonNull(catalogue);clients=new RatisClientPool(16,leaders,owners);}
    private synchronized void enter()throws IOException{if(closing || active>=16)throw new IOException("Relocation transport unavailable");active++;}private synchronized void leave(){active--;notifyAll();}
    private void require(TopologyChange.Definition definition)throws IOException{if(definition.kind()!=TopologyChange.Kind.RELOCATE || !cluster.equals(definition.header().clusterId()) || !database.equals(definition.header().databaseId()))throw new IOException("Relocation namespace differs");}
    public RatisRelocationOwnerRpc.Evidence read(RatisRelocationOwnerRpc.Request request)throws IOException{
        require(request.definition());var descriptor=request.expected()==RatisRelocationOwnerRpc.Expected.SOURCE?request.definition().parents().getFirst():request.definition().targets().getFirst();var peer=request.replica()==null?null:descriptor.replicas().stream().filter(r->r.replicaId().equals(request.replica())).findFirst().orElseThrow();enter();try(var lease=peer==null?clients.acquire(descriptor):clients.acquireOwner(descriptor,peer)){byte[] bytes=RatisRelocationOwnerRpc.request(request);var reply=RatisRoutedClient.rpc(()->peer==null?lease.client().io().sendReadOnly(message(bytes)):lease.client().io().sendStaleRead(message(bytes),0,RaftPeerId.valueOf(peer.peerId())));byte[] output=content(reply,descriptor.groupId(),RatisRelocationOwnerRpc.MAX_REPLY_BYTES);try{var evidence=RatisRelocationOwnerRpc.decodeReply(output,request);var owner=(request.expected()==RatisRelocationOwnerRpc.Expected.SOURCE?request.definition().parents().getFirst():descriptor).replicas().stream().filter(r->r.replicaId().equals(evidence.owner().replicaId())).findFirst().orElseThrow();if(!RaftPeerId.valueOf(owner.peerId()).equals(reply.getServerId()))throw new IOException("Relocation owner reply crossed actual peer");return evidence;}catch(IllegalArgumentException invalid){throw new IOException("Invalid actual relocation evidence",invalid);}}finally{leave();}
    }
    public RatisTopologySourceSnapshotRpc.Prepared prepare(RatisTopologySourceSnapshotRpc.Request request,TopologyChange.Definition definition)throws IOException{return source(request,definition,RatisTopologySourceSnapshotRpc.PREPARE);}
    public RatisTopologySourceSnapshotRpc.Prepared transfer(RatisTopologySourceSnapshotRpc.Request request,TopologyChange.Definition definition)throws IOException{return source(request,definition,RatisTopologySourceSnapshotRpc.TRANSFER);}
    private RatisTopologySourceSnapshotRpc.Prepared source(RatisTopologySourceSnapshotRpc.Request request,TopologyChange.Definition definition,int action)throws IOException{require(definition);request.header().requireDefinition(definition);if(!catalogue.equals(request.catalogue()))throw new IOException("Source catalogue differs");enter();try(var lease=clients.acquire(definition.parents().getFirst())){var source=new RatisTopologySourceSnapshotClient(lease.client());return action==RatisTopologySourceSnapshotRpc.PREPARE?source.prepare(request):source.transfer(request);}finally{leave();}}
    public void release(RatisTopologySourceSnapshotRpc.Request request,TopologyChange.Definition definition)throws IOException{require(definition);request.header().requireDefinition(definition);if(!catalogue.equals(request.catalogue()))throw new IOException("Source catalogue differs");enter();try(var lease=clients.acquire(definition.parents().getFirst())){new RatisTopologySourceSnapshotClient(lease.client()).release(request);}finally{leave();}}
    public void append(RatisTopologyRelocationRecord record)throws IOException{
        require(record.definition());if(!catalogue.equals(record.catalogue()))throw new IOException("Relocation catalogue differs");var range=record.action()==RatisTopologyRelocationRecord.Action.AUTHORIZE?record.definition().parents().getFirst():record.definition().targets().getFirst();enter();try(var lease=clients.acquire(range)){var client=lease.client();var prepared=RatisRoutedClient.rpc(()->client.io().sendReadOnly(message(RatisRelocationAdmissionRpc.request(RatisRelocationAdmissionRpc.PREPARE,record))));RatisRelocationAdmissionRpc.requireEcho(content(prepared,range.groupId(),RatisRelocationAdmissionRpc.MAX_BYTES),RatisRelocationAdmissionRpc.PREPARE,record);var reply=RatisRoutedClient.rpc(()->client.io().send(message(record.encode())));var result=content(reply,range.groupId(),NativeTopologyRelocationCompletion.MAX_BYTES);if(result.length==8){if(CommandResult.decode(result).status()!=CommandResult.Status.SUCCESS)throw new IOException("Relocation append rejected");}else NativeTopologyRelocationCompletion.decode(result).requireRequest(record.definition(),record.targetConfiguration(),catalogue,record.catalogueCut());}finally{leave();}
    }
    public NativeTopologyLearnerRegistration join(TopologyChange.Definition definition,ReplicaDescriptor receiver,RangeDescriptor anchor,ReplicaDescriptor anchorOwner)throws IOException{
        require(definition);if(!receiver.nodeId().equals(anchorOwner.nodeId()) || !receiver.nodeIncarnation().equals(anchorOwner.nodeIncarnation()) || !receiver.peerId().equals(anchorOwner.peerId()) || !receiver.address().equals(anchorOwner.address()))throw new IOException("Receiver anchor differs from configured node identity");var request=RatisTopologyJoinAuthority.Request.of(definition,receiver.replicaId());enter();try(var lease=clients.acquireOwner(anchor,anchorOwner)){var reply=RatisRoutedClient.rpc(()->lease.client().io().sendStaleRead(message(RatisTopologyLearnerJoinRpc.request(request)),0,RaftPeerId.valueOf(receiver.peerId())));if(reply==null || !RaftPeerId.valueOf(receiver.peerId()).equals(reply.getServerId()))throw new IOException("Learner join crossed receiver");return RatisTopologyLearnerJoinRpc.reply(content(reply,anchor.groupId(),RatisTopologyLearnerJoinRpc.MAX_REPLY_BYTES),request);}finally{leave();}
    }
    public RatisTopologySourceSnapshotRpc.Prepared recover(RatisTopologySourceSnapshotRpc.Request request,TopologyChange.Definition definition)throws IOException{
        require(definition);request.header().requireDefinition(definition);if(!catalogue.equals(request.catalogue()) || request.purpose()!=RatisTopologySourceSnapshotRpc.Purpose.RECOVERY)throw new IOException("Registered recovery binding differs");
        var source=definition.parents().getFirst();var owner=source.replicas().stream().filter(r->r.replicaId().equals(request.receiver().replicaId())).findFirst().orElseThrow(()->new IOException("Recovery receiver has no source registration"));
        enter();try(var lease=clients.acquireOwner(source,owner)){var reply=RatisRoutedClient.rpc(()->lease.client().io().sendStaleRead(message(RatisTopologyLearnerRecoveryRpc.request(request)),0,RaftPeerId.valueOf(owner.peerId())));if(reply==null || !RaftPeerId.valueOf(owner.peerId()).equals(reply.getServerId()))throw new IOException("Recovery crossed receiver");try{return RatisTopologyLearnerRecoveryRpc.reply(content(reply,source.groupId(),RatisTopologyLearnerRecoveryRpc.MAX_REPLY_BYTES),request);}catch(IllegalArgumentException invalid){throw new IOException("Invalid recovery image reply",invalid);}}finally{leave();}
    }
    public void compareAndSet(TopologyChange.Definition definition,byte[] frozenSourceConfiguration,byte[] targetConfiguration,RatisTopologyJoinAuthority.Client authority)throws IOException{
        require(definition);Objects.requireNonNull(authority);enter();try{var actor=definition.parents().getFirst().replicas().stream().filter(r->r.role()==ReplicaDescriptor.Role.VOTER).findFirst().orElseThrow();var query=RatisTopologyJoinAuthority.Request.of(definition.header(),actor.replicaId(),RatisTopologyJoinAuthority.Purpose.SOURCE_CONFIGURATION);var view=authority.read(query);view.require(query);if(!catalogue.equals(view.catalogue()) || view.state().phase()!=TopologyChange.Phase.JOINING || !Arrays.equals(view.definition().encode(),definition.encode()))throw new IOException("Configuration CAS lacks irreversible committed JOINING");RatisRangeStateMachine.requireSchemaMembership(definition.parents().getFirst(),frozenSourceConfiguration);RatisRangeStateMachine.requireSchemaMembership(definition.targets().getFirst(),targetConfiguration);var source=RaftConfigurationProto.parseFrom(frozenSourceConfiguration);var target=RaftConfigurationProto.parseFrom(targetConfiguration);var arguments=SetConfigurationRequest.Arguments.newBuilder().setMode(SetConfigurationRequest.Mode.COMPARE_AND_SET).setServersInCurrentConf(peers(source.getPeersList())).setListenersInCurrentConf(peers(source.getListenersList())).setServersInNewConf(peers(target.getPeersList())).setListenersInNewConf(peers(target.getListenersList())).build();try(var lease=clients.acquire(definition.parents().getFirst())){var reply=RatisRoutedClient.rpc(()->lease.client().admin().setConfiguration(arguments));if(reply==null || !reply.isSuccess() || !RaftGroupId.valueOf(definition.parents().getFirst().groupId()).equals(reply.getRaftGroupId()))throw new IOException("Conditional relocation configuration outcome remains unresolved",reply==null?null:reply.getException());}}finally{leave();}
    }
    static byte[] targetConfiguration(RangeDescriptor target,byte[] source)throws IOException{var old=RaftConfigurationProto.parseFrom(source);var known=new HashMap<String,RaftPeerProto>();for(var p:old.getPeersList())known.put(p.getId().toStringUtf8(),p);for(var p:old.getListenersList())known.put(p.getId().toStringUtf8(),p);var builder=RaftConfigurationProto.newBuilder();for(var r:target.replicas().stream().sorted(Comparator.comparing(ReplicaDescriptor::peerId)).toList()){var base=known.get(r.peerId());var peer=base==null?RaftPeer.newBuilder().setId(r.peerId()).setAddress(r.address()):RaftPeer.newBuilder(org.apache.ratis.util.ProtoUtils.toRaftPeer(base));peer.setAddress(r.address());peer.setStartupRole(r.role()==ReplicaDescriptor.Role.LISTENER?RaftPeerRole.LISTENER:RaftPeerRole.FOLLOWER);if(r.role()==ReplicaDescriptor.Role.LISTENER)builder.addListeners(peer.build().getRaftPeerProto());else builder.addPeers(peer.build().getRaftPeerProto());}return builder.build().toByteArray();}
    private static List<RaftPeer> peers(List<RaftPeerProto> peers){return org.apache.ratis.util.ProtoUtils.toRaftPeers(peers);}
    private static Message message(byte[] bytes){return Message.valueOf(ByteString.copyFrom(bytes));}
    private static byte[] content(RaftClientReply reply,UUID group,int maximum)throws IOException{if(reply==null || !reply.isSuccess() || reply.getMessage()==null || !RaftGroupId.valueOf(group).equals(reply.getRaftGroupId()) || reply.getMessage().getContent().size()>maximum)throw new IOException("Relocation RPC failed/crossed group",reply==null?null:reply.getException());return reply.getMessage().getContent().toByteArray();}
    private static RaftClient connected(RangeDescriptor range,ReplicaDescriptor owner){var properties=new RaftProperties();org.apache.ratis.RaftConfigKeys.Rpc.setType(properties,org.apache.ratis.rpc.SupportedRpcType.GRPC);GrpcConfigKeys.setMessageSizeMax(properties,SizeInBytes.valueOf(RatisTopologySourceSnapshotRpc.MAX_REPLY_BYTES+4096L));var group=RaftGroup.valueOf(RaftGroupId.valueOf(range.groupId()),range.replicas().stream().map(r->RaftPeer.newBuilder().setId(r.peerId()).setAddress(r.address()).setStartupRole(r.role()==ReplicaDescriptor.Role.LISTENER?RaftPeerRole.LISTENER:RaftPeerRole.FOLLOWER).build()).toList());var builder=RaftClient.newBuilder().setRaftGroup(group).setProperties(properties);if(owner!=null)builder.setLeaderId(RaftPeerId.valueOf(owner.peerId()));return builder.build();}
    @Override public synchronized void close()throws IOException{closing=true;if(active!=0)throw new IOException("Actual relocation calls remain active");clients.close();}
}
